-- Generated localized release notes.
local _, namespace = ...
namespace.releaseNotesByLocale = {["deDE"]={["sections"]={{["items"]={"Folgst du dem Questfokus eines Gruppenmitglieds, löst der automatische Fokuswechsel beim Annehmen einer Quest keine Rückfrage zum Beenden mehr aus. Das Folgen bleibt aktiv; die gemeinsame Quest wird wieder ausgewählt, sobald das Spiel es zulässt.","Wählst du später selbst eine andere Quest aus, erscheint weiterhin die Rückfrage, ob du dem Gruppenmitglied nicht mehr folgen möchtest."},["title"]="Quests annehmen und weiter folgen"},{["items"]={"Wenn WoW auf freundlichen Namensplaketten nur Namen anzeigt, sitzt das QT-Symbol jetzt direkt links neben dem sichtbaren Namen. Schaltest du diese Option aus, wird die gespeicherte QT-Symbolposition wieder verwendet."},["title"]="Freundliche Namensplaketten ohne Balken"}},["version"]="9.3.2",["welcome"]="Korrekturen für den Questfokus beim Annehmen neuer Quests und für QT-Symbole neben freundlichen Spielernamen."},["esES"]={["sections"]={{["items"]={"Al aceptar una misión, el cambio automático de misión activa ya no interrumpe el seguimiento de un compañero ni pide confirmar que quieres dejar de seguirlo. El seguimiento sigue activo y se recupera la misión compartida en cuanto WoW lo permite.","Si después eliges otra misión por tu cuenta, se sigue mostrando la confirmación para dejar de seguir al compañero."},["title"]="Aceptar misiones durante el seguimiento"},{["items"]={"Cuando WoW muestra solo los nombres de los jugadores amistosos, el icono de QT queda justo a la izquierda del texto del nombre, en lugar de junto a la barra de salud oculta. Al desactivar esa opción, el icono vuelve a la posición que tenías guardada."},["title"]="Placas amistosas con solo nombres"}},["version"]="9.3.2",["welcome"]="Corregidos el seguimiento al aceptar misiones y la posición del icono de QT en las placas amistosas que solo muestran nombres."},["esMX"]={["sections"]={{["items"]={"Si WoW selecciona automáticamente una misión que acabas de aceptar, ya no aparece la confirmación para dejar de seguir a tu compañero. El seguimiento se mantiene y la misión compartida vuelve a quedar activa en cuanto el juego lo permite.","Cuando eliges otra misión por tu cuenta más adelante, la confirmación para dejar de seguir sigue apareciendo como antes."},["title"]="Aceptar misiones durante el seguimiento"},{["items"]={"Con la opción de WoW para mostrar solo los nombres de jugadores amistosos, el ícono de QT se coloca justo a la izquierda del texto del nombre, en vez de junto a la barra de salud oculta. Si desactivas la opción, vuelve a la posición que guardaste."},["title"]="Placas amistosas con solo nombres"}},["version"]="9.3.2",["welcome"]="Esta actualización corrige el seguimiento al aceptar misiones y la posición del ícono de QT en las placas amistosas que muestran solo nombres."},["frFR"]={["sections"]={{["items"]={"Lorsqu’une quête acceptée devient automatiquement votre quête active, vous continuez à suivre votre compagnon sans demande d’arrêt. La quête commune est rétablie dès que le jeu le permet.","Si vous choisissez ensuite vous-même une autre quête, la confirmation d’arrêt du suivi reste nécessaire."},["title"]="Accepter des quêtes pendant un suivi"},{["items"]={"Quand WoW affiche uniquement les noms des joueurs alliés sur leurs barres d’info, l’icône QT se place juste à gauche du nom visible. Désactiver cette option rétablit la position enregistrée de l’icône."},["title"]="Barres d’info alliées affichant uniquement les noms"}},["version"]="9.3.2",["welcome"]="Corrections du suivi lors de l’acceptation de quêtes et du placement des icônes QT quand seuls les noms des joueurs alliés sont affichés."},["itIT"]={["sections"]={{["items"]={"Quando accetti una missione mentre segui quella di un compagno, il cambio automatico di selezione non ti chiede più di smettere di seguirlo. Continui a seguirlo e la missione condivisa viene ripristinata appena il gioco lo consente.","Se in seguito scegli tu un’altra missione, compare ancora la conferma per smettere di seguire il compagno."},["title"]="Accettare missioni mentre segui un compagno"},{["items"]={"Quando WoW mostra solo i nomi sulle targhette dei giocatori amichevoli, l’icona QT si posiziona subito a sinistra del nome visibile. Disattivando questa opzione, l’icona torna nella posizione che avevi salvato."},["title"]="Targhette amichevoli con il solo nome"}},["version"]="9.3.2",["welcome"]="Correzioni per chi segue la missione di un compagno e per le icone QT sulle targhette amichevoli che mostrano solo il nome."},["koKR"]={["sections"]={{["items"]={"파티원의 집중 퀘스트를 따라가는 동안 새 퀘스트를 수락해 집중 퀘스트가 자동으로 바뀌어도, 이제 따라가기 중지 확인창이 뜨지 않습니다. 따라가기는 유지되며 게임에서 변경을 허용하면 파티원이 선택한 퀘스트로 다시 맞춰집니다.","이후 직접 다른 퀘스트를 선택할 때는 기존처럼 따라가기를 중지할지 확인합니다."},["title"]="따라가기 중 퀘스트 수락"},{["items"]={"우호적 플레이어의 이름표를 이름만 표시하도록 설정하면 QT 아이콘이 실제 이름 글자 바로 왼쪽에 배치됩니다. 이 설정을 끄면 저장해 둔 아이콘 위치로 돌아갑니다."},["title"]="이름만 표시하는 우호적 이름표"}},["version"]="9.3.2",["welcome"]="새 퀘스트 수락 시 집중 퀘스트 따라가기가 끊기는 문제와 이름만 표시하는 우호적 플레이어 이름표의 QT 아이콘 위치를 수정했습니다."},["ptBR"]={["sections"]={{["items"]={"A seleção automática de uma missão recém-aceita não interrompe mais o acompanhamento da missão em foco de um integrante do grupo nem pede confirmação para parar de seguir. O acompanhamento permanece ativo, e a missão compartilhada volta ao foco assim que o WoW permite.","Se você escolher outra missão por conta própria depois disso, a confirmação para parar de seguir continua aparecendo normalmente."},["title"]="Aceitar missões durante o acompanhamento"},{["items"]={"Com a opção do WoW de exibir apenas os nomes de jogadores aliados, o ícone do QT fica logo à esquerda do texto do nome, em vez de acompanhar a barra de vida oculta. Ao desativar a opção, o ícone retorna à posição que você salvou."},["title"]="Placas aliadas com apenas nomes"}},["version"]="9.3.2",["welcome"]="Correções no acompanhamento ao aceitar missões e na posição do ícone do QT nas placas de jogadores aliados que exibem apenas nomes."},["ruRU"]={["sections"]={{["items"]={"Если вы следуете выбору задания участника группы, автоматическое переключение при получении нового задания больше не вызывает запрос на прекращение следования. Следование сохраняется, а выбор задания снова синхронизируется с напарником, когда игра разрешает переключение.","Если позже вы сами выберете другое задание, подтверждение прекращения следования появится, как и прежде."},["title"]="Получение заданий во время следования"},{["items"]={"В режиме показа только имён дружественных игроков значок QT теперь размещается непосредственно слева от текста имени. При отключении этого режима возвращается сохранённое положение значка."},["title"]="Значки рядом с именами союзников"}},["version"]="9.3.2",["welcome"]="Исправлены следование выбранному заданию при получении новых заданий и положение значков QT рядом с именами союзников."},["zhCN"]={["sections"]={{["items"]={"跟随队友的任务选择时，接取新任务引起的自动切换不再弹出停止跟随的确认。跟随会保持开启，并在游戏允许切换时恢复到双方当前共同追踪的任务。","之后主动选择其他任务，仍会照常询问是否停止跟随。"},["title"]="跟随期间接取任务"},{["items"]={"友方玩家姓名板设为仅显示名字时，QT 图标现在会显示在名字文字的左侧。关闭此设置后，图标会恢复到你保存的位置。"},["title"]="仅显示名字的友方姓名板"}},["version"]="9.3.2",["welcome"]="修复接取任务时的任务跟随问题，并调整友方姓名板仅显示名字时的 QT 图标位置。"},["zhTW"]={["sections"]={{["items"]={"跟隨隊友的任務選擇時，接取新任務造成的自動切換不再要求確認停止跟隨。跟隨狀態會保留，並在遊戲允許切換時回到目前共同追蹤的任務。","之後若自行選擇其他任務，仍會照常詢問是否結束跟隨。"},["title"]="跟隨時接取新任務"},{["items"]={"將友方玩家名條設為只顯示名字時，QT 圖示現在會緊鄰名字文字的左側顯示。關閉此設定後，就會恢復原先儲存的圖示位置。"},["title"]="只顯示名字的友方名條"}},["version"]="9.3.2",["welcome"]="修正接取新任務時的任務跟隨問題，以及友方名條只顯示名字時的 QT 圖示位置。"}}
